private static int decodeOctets(int i, ByteBuffer bb, StringBuilder sb) {
    // Ensure there is at least one byte available
    if (bb.remaining() < 1) {
        throw new IllegalArgumentException("ByteBuffer has no bytes to read");
    }

    // Read the first byte and treat it as unsigned
    int b0 = bb.get(i) & 0xFF;
    int currIndex = i + 1; // index after the first byte

    if ((b0 & 0x80) == 0x00) { // 1-byte ASCII
        sb.append((char) b0);
        return currIndex;
    }

    int continuationCount;
    int codePoint;

    if ((b0 & 0xE0) == 0xC0) { // 2-byte sequence
        continuationCount = 1;
        if (bb.remaining() < continuationCount) {
            throw new IllegalArgumentException("Incomplete UTF-8 sequence at index " + i);
        }
        int b1 = bb.get(currIndex) & 0xFF;
        currIndex++;
        if ((b1 & 0xC0) != 0x80) {
            throw new IllegalArgumentException("Invalid continuation byte at index " + (currIndex - 1));
        }
        codePoint = ((b0 & 0x1F) << 6) | (b1 & 0x3F);
        if (codePoint < 0x80) { // Overlong encoding
            throw new IllegalArgumentException("Overlong UTF-8 encoding at index " + i);
        }
    } else if ((b0 & 0xF0) == 0xE0) { // 3-byte sequence
        continuationCount = 2;
        if (bb.remaining() < continuationCount) {
            throw new IllegalArgumentException("Incomplete UTF-8 sequence at index " + i);
        }
        int b1 = bb.get(currIndex) & 0xFF;
        currIndex++;
        int b2 = bb.get(currIndex) & 0xFF;
        currIndex++;
        if (((b1 & 0xC0) != 0x80) || ((b2 & 0xC0) != 0x80)) {
            throw new IllegalArgumentException("Invalid continuation byte in 3-byte sequence at index " + (currIndex - 2));
        }
        codePoint = ((b0 & 0x0F) << 12) | ((b1 & 0x3F) << 6) | (b2 & 0x3F);
        if (codePoint < 0x800) { // Overlong encoding
            throw new IllegalArgumentException("Overlong UTF-8 encoding at index " + i);
        }
    } else if ((b0 & 0xF8) == 0xF0) { // 4-byte sequence
        continuationCount = 3;
        if (bb.remaining() < continuationCount) {
            throw new IllegalArgumentException("Incomplete UTF-8 sequence at index " + i);
        }
        int b1 = bb.get(currIndex) & 0xFF;
        currIndex++;
        int b2 = bb.get(currIndex) & 0xFF;
        currIndex++;
        int b3 = bb.get(currIndex) & 0xFF;
        currIndex++;
        if (((b1 & 0xC0) != 0x80) || ((b2 & 0xC0) != 0x80) || ((b3 & 0xC0) != 0x80)) {
            throw new IllegalArgumentException("Invalid continuation byte in 4-byte sequence at index " + (currIndex - 3));
        }
        codePoint = ((b0 & 0x07) << 18)
                | ((b1 & 0x3F) << 12)
                | ((b2 & 0x3F) << 6)
                | (b3 & 0x3F);
        if (codePoint < 0x10000 || codePoint > 0x10FFFF) {
            throw new IllegalArgumentException("UTF-8 code point out of range at index " + i);
        }
    } else {
        throw new IllegalArgumentException("Invalid UTF-8 leading byte at index " + i);
    }

    // Append the decoded character(s)
    if (codePoint <= 0xFFFF) {
        sb.append((char) codePoint);
    } else {
        // Encode surrogate pair
        codePoint -= 0x10000;
        char highSurrogate = (char) ((codePoint >> 10) + 0xD800);
        char lowSurrogate = (char) ((codePoint & 0x3FF) + 0xDC00);
        sb.append(highSurrogate).append(lowSurrogate);
    }

    return currIndex;
}

