/** Helper that recursively schedules a file or directory for deletion. */
private static void scheduleDeleteOnExit(File f) throws IOException {
    if (f.isDirectory()) {
        File[] children = f.listFiles();
        if (children == null) { // null indicates an I/O error or lack of permissions
            throw new IOException("Unable to access directory: " + f.getAbsolutePath());
        }
        for (File child : children) {
            scheduleDeleteOnExit(child);
        }
    }
    f.deleteOnExit();
}

