@Override
public void generateGraph(Graph<V, E> target, Map<String, V> resultMap) {
    if (target == null) {
        throw new IllegalArgumentException("Target graph must not be null.");
    }
    if (resultMap == null) {
        throw new IllegalArgumentException("Result map must not be null.");
    }

    // Define the sizes of the two partitions
    final int leftSize = 4;  // number of vertices in the first partition
    final int rightSize = 3; // number of vertices in the second partition

    try {
        // Create vertices for the left partition
        for (int i = 1; i <= leftSize; i++) {
            String id = "U" + i;
            @SuppressWarnings("unchecked")
            V vertex = (V) id;
            target.addVertex(vertex);
            resultMap.put(id, vertex);
        }

        // Create vertices for the right partition
        for (int j = 1; j <= rightSize; j++) {
            String id = "V" + j;
            @SuppressWarnings("unchecked")
            V vertex = (V) id;
            target.addVertex(vertex);
            resultMap.put(id, vertex);
        }

        // Add all edges between partitions (complete bipartite)
        for (int i = 1; i <= leftSize; i++) {
            String leftId = "U" + i;
            V u = resultMap.get(leftId);
            for (int j = 1; j <= rightSize; j++) {
                String rightId = "V" + j;
                V v = resultMap.get(rightId);
                target.addEdge(u, v);
            }
        }
    } catch (RuntimeException ex) {
        throw new IllegalArgumentException("Failed to generate bipartite graph: " + ex.getMessage(), ex);
    }
}

protected int findByte(byte value, int pos) {
    // Ensure the buffer exists
    if (buffer == null) {
        // If buffer is not initialized, we cannot search; return -1 to indicate not found
        return -1;
    }
    int len = buffer.length;

    // Clamp the starting position to a valid range
    if (pos < 0) {
        pos = 0;
    }
    if (pos >= len) {
        return -1; // starting position beyond the buffer; nothing to find
    }

    // Search linearly from the starting position
    for (int i = pos; i < len; i++) {
        if (buffer[i] == value) {
            return i; // byte found at this index
        }
    }
    return -1; // value not found in the buffer
}

public static <T> int writeDelimitedTo(OutputStream out, T message, Schema<T> schema, LinkedBuffer buffer) throws IOException {
    if (out == null) {
        throw new IllegalArgumentException("OutputStream cannot be null");
    }
    if (message == null) {
        throw new IllegalArgumentException("Message cannot be null");
    }
    if (schema == null) {
        throw new IllegalArgumentException("Schema cannot be null");
    }

    // Determine the cached size of the message
    int size = schema.getCachedSize(message);
    if (size < 0) {
        throw new IOException("Cached size cannot be negative");
    }

    // Use a CodedOutputStream to write the size as a varint followed by the message
    try {
        // Write the length prefix
        CodedOutputStream cos = CodedOutputStream.newInstance(out);
        cos.writeRawVarint32(size);
        // Serialize the message
        schema.serializeToCodedOutputStream(message, cos);
        cos.flush();
        return size;
    } catch (IOException e) {
        // Propagate the exception to the caller
        throw e;
    } catch (Exception e) {
        // Wrap any other exception as IOException
        throw new IOException("Failed to write delimited message", e);
    }
}

