void insertBefore(Bucket bucket){
    // Validate input
    if (bucket == null) {
        throw new IllegalArgumentException("bucket must not be null");
    }
    if (bucket == this) {
        throw new IllegalArgumentException("cannot insert before itself");
    }

    /* Detach this bucket from any existing links to avoid dangling references or cycles.
       If this bucket is already in a list, adjust the adjacent nodes’ pointers. */
    if (this.prev != null) {
        this.prev.next = this.next;
    }
    if (this.next != null) {
        this.next.prev = this.prev;
    }

    /* Link this bucket before the supplied bucket. */
    Bucket prevNode = bucket.prev;
    this.prev = prevNode;
    this.next = bucket;
    bucket.prev = this;
    if (prevNode != null) {
        prevNode.next = this;
    }
}

