    }
    // List of commonly used method names that might register a consumer
    String[] candidateNames = {"addConsumer", "registerConsumer", "subscribe", "attach", "addTarget", "add"};
    java.lang.reflect.Method matched = null;
    for (String name : candidateNames) {
        try {
            matched = channels.getClass().getMethod(name, IConsumer.class);
            if (matched != null) {
                break;
            }
        } catch (NoSuchMethodException e) {
            // Continue searching
        }
    }
    // If no known method was found, try to find any method that accepts a single IConsumer argument
    if (matched == null) {
        java.lang.reflect.Method[] methods = channels.getClass().getMethods();
        for (java.lang.reflect.Method m : methods) {
            Class<?>[] params = m.getParameterTypes();
            if (params.length == 1 && IConsumer.class.isAssignableFrom(params[0])) {
                matched = m;
                break;
            }
        }
    }
    if (matched == null) {
        throw new IllegalStateException("No suitable method found on Channels to register consumer");
    }
    try {
        matched.invoke(channels, consumer);
