        throw new RuntimeException("Failed to invoke method to add consumer", e);
    }
}

public static void createConfigurationDirectory() {
    // Determine the base directory where the configuration folder should be created
    String osName = System.getProperty("os.name");
    String basePath = null;
    if (osName != null && osName.startsWith("Windows 2000")) {
        // On Windows 2000, use the parent of the user's home directory (Documents and Settings)
        String userHome = System.getProperty("user.home");
        if (userHome != null) {
            java.io.File userHomeFile = new java.io.File(userHome);
            java.io.File parent = userHomeFile.getParentFile();
            basePath = (parent != null) ? parent.getAbsolutePath() : userHome;
        }
    }
    if (basePath == null) {
        // For all other platforms, use the user.home property
        basePath = System.getProperty("user.home");
        if (basePath == null) {
            // Fallback to the current working directory if user.home is unavailable
            basePath = ".";
        }
    }

    java.io.File configDir = new java.io.File(basePath, "lf5");
    if (!configDir.exists()) {
        try {
            boolean created = configDir.mkdirs();
            if (!created && !configDir.exists()) {
                // mkdirs might fail silently if the directory already exists,
                // but if it still does not exist, throw an exception.
                throw new IllegalStateException(
                    "Failed to create configuration directory: " + configDir.getAbsolutePath());
            }
        } catch (SecurityException se) {
            throw new IllegalStateException(
                "No permission to create configuration directory: " + configDir.getAbsolutePath(), se);
        }
    }
}

