protected List<TimeRange> buildTimeRanges(long start, long end) {
    // Validate input
    if (start > end) {
        throw new IllegalArgumentException("start must be less than or equal to end");
    }
    // Ensure FETCH_DATA_DURATION is positive
    long maxDuration = FETCH_DATA_DURATION;
    if (maxDuration <= 0) {
        throw new IllegalStateException("FETCH_DATA_DURATION must be a positive value");
    }
    List<TimeRange> ranges = new ArrayList<>();
    long currentStart = start;
    while (currentStart < end) {
        long currentEnd = Math.min(currentStart + maxDuration, end);
        ranges.add(new TimeRange(currentStart, currentEnd));
        currentStart = currentEnd;
    }
    return ranges;
}

