static long compressTimeBucket(long timeBucket, int dayStep) {
    // Validate inputs
    if (dayStep <= 0) {
        throw new IllegalArgumentException("dayStep must be a positive integer");
    }
    if (timeBucket <= 0) {
        throw new IllegalArgumentException("timeBucket must be a positive integer");
    }
    try {
        long year = timeBucket / 10000L;
        long monthDayPart = timeBucket % 10000L;
        long month = monthDayPart / 100L;
        long day = monthDayPart % 100L;

        // Basic sanity checks for month/day – if invalid, return original bucket
        if (month < 1 || month > 12 || day < 1 || day > 31) {
            return timeBucket;
        }

        long bucketDay = ((day - 1) / dayStep) * dayStep + 1;
        return year * 10000L + month * 100L + bucketDay;
    } catch (Exception e) {
        // In the unlikely event of an overflow or other runtime issue, fallback to the original value
        return timeBucket;
    }
}

public static int computeUTF8Size(final CharSequence str, final int index, final int len) {
    if (str == null) {
        throw new IllegalArgumentException("String cannot be null");
    }
    if (index < 0 || len < 0 || index + len > str.length()) {
        throw new IllegalArgumentException("Invalid index or length");
    }
    int size = 0;
    int end = index + len;
    for (int i = index; i < end; ) {
        char ch = str.charAt(i);
        if (ch <= 0x7F) {
            size += 1;
        } else if (ch <= 0x7FF) {
            size += 2;
        } else if (Character.isHighSurrogate(ch)) {
            if (i + 1 < end && Character.isLowSurrogate(str.charAt(i + 1))) {
                // Surrogate pair => 4 bytes
                size += 4;
                i++; // Skip low surrogate
            } else {
                // Unpaired high surrogate => replacement character U+FFFD (3 bytes)
                size += 3;
            }
        } else if (Character.isLowSurrogate(ch)) {
            // Unpaired low surrogate => replacement character U+FFFD (3 bytes)
            size += 3;
        } else {
            size += 3;
        }
        i++;
    }
    return size;
}

