    }

    // Use regionMatches for efficiency and optional case insensitivity
    return str.regionMatches(ignoreCase, strLen - suffixLen, suffix, 0, suffixLen);
}

public static List<PathSegmentImpl> decodePath(URI u, boolean decode) {
    if (u == null) {
        throw new IllegalArgumentException("URI cannot be null");
    }

    String rawPath = u.getRawPath();
    if (rawPath == null || rawPath.isEmpty()) {
        return Collections.emptyList();
    }

    // Remove leading '/' if present (absolute path)
    if (rawPath.startsWith("/")) {
        rawPath = rawPath.substring(1);
    }

    String[] rawSegments = rawPath.split("/");
    List<PathSegmentImpl> segments = new ArrayList<>(rawSegments.length);

    for (String rawSeg : rawSegments) {
        if (rawSeg.isEmpty()) {
            // Skip empty segments (e.g., due to consecutive slashes or trailing slash)
            continue;
        }
        String decodedSeg;
        if (decode) {
            try {
                // URLDecoder treats '+' as space, so replace '+' with its percent-encoding
                String sanitized = rawSeg.replace("+", "%2B");
                decodedSeg = java.net.URLDecoder.decode(sanitized, "UTF-8");
            } catch (UnsupportedEncodingException e) {
                // UTF-8 is guaranteed to be supported, rethrow as runtime
                throw new IllegalArgumentException("UTF-8 encoding not supported", e);
            }
        } else {
            decodedSeg = rawSeg;
        }
        segments.add(new PathSegmentImpl(decodedSeg));
    }

    return segments;
}

