private void enlarge(final int size) {
    if (size < 0) {
        throw new IllegalArgumentException("size must be non‑negative, got: " + size);
    }
    if (size == 0) {
        return;
    }
    try {
        // Assuming the underlying buffer is stored in a byte array named `bytes`.
        // The current data length is `bytes.length`; the vector may have a logical
        // size field that tracks how many bytes are actually used (e.g., `count`).
        // We enlarge the buffer so that `bytes.length + size` bytes can be stored.
        int currentCapacity = bytes.length;
        // Determine the new capacity: double until it can hold the requested size.
        long newCapLong = Math.max(currentCapacity * 2L, currentCapacity + size);
        if (newCapLong > Integer.MAX_VALUE) {
            // In practice this would be an OutOfMemoryError in real usage, but we
            // throw it explicitly to provide a clear message.
            throw new OutOfMemoryError("Requested buffer size exceeds maximum array size");
        }
        int newCapacity = (int) newCapLong;
        byte[] newBytes = new byte[newCapacity];
        System.arraycopy(bytes, 0, newBytes, 0, count); // copy only used bytes
        bytes = newBytes;
    } catch (NegativeArraySizeException | OutOfMemoryError e) {
        // Fail gracefully by rethrowing the exception with context.
        throw e;
    }
}

