@Override protected Object convertToType(final Class<?> type, final Object value) throws Exception {
    // Allow conversion only when target type is Character or char
    if (type != null && !Character.class.equals(type) && !char.class.equals(type)) {
        throw new Exception("Target type is not Character");
    }

    if (value == null) {
        return null;
    }

    // If already a Character instance, return as is
    if (value instanceof Character) {
        return value;
    }

    // If it's a Number, use its int value as char code
    if (value instanceof Number) {
        int intVal = ((Number) value).intValue();
        if (intVal < Character.MIN_VALUE || intVal > Character.MAX_VALUE) {
            throw new Exception("Numeric value out of character range: " + intVal);
        }
        return Character.valueOf((char) intVal);
    }

    // If it's a String, it must be length 1 to convert
    if (value instanceof String) {
        String str = (String) value;
        if (str.length() == 1) {
            return Character.valueOf(str.charAt(0));
        } else {
            throw new Exception("String length is not 1: \"" + str + "\"");
        }
    }

    // For any other type, attempt to use its string representation
    String str = value.toString();
    if (str.length() == 1) {
        return Character.valueOf(str.charAt(0));
    } else {
        throw new Exception("Cannot convert value to Character: " + value);
    }
}

