public static int nextPrime(int desiredCapacity) {
    if (desiredCapacity <= 2) {
        return 2;
    }
    int candidate = desiredCapacity;
    if (candidate % 2 == 0) {
        candidate++; // make it odd
    }
    while (true) {
        boolean prime = true;
        if (candidate == 2 || candidate == 3) {
            prime = true;
        } else if (candidate <= 1 || candidate % 2 == 0 || candidate % 3 == 0) {
            prime = false;
        } else {
            for (int i = 5; (long) i * i <= candidate; i += 6) {
                if (candidate % i == 0 || candidate % (i + 2) == 0) {
                    prime = false;
                    break;
                }
            }
        }
        if (prime) {
            return candidate;
        }
        if (candidate > Integer.MAX_VALUE - 2) {
            throw new IllegalArgumentException("No prime found in integer range");
        }
        candidate += 2;
    }
}

