private Map<String,Object> buildContent(JsonObject jsonObject){
    Map<String,Object> result = new LinkedHashMap<>();
    if(jsonObject == null){
        return result;
    }
    try{
        for(Map.Entry<String,JsonElement> entry : jsonObject.entrySet()){
            String key = entry.getKey();
            JsonElement value = entry.getValue();
            result.put(key, convertJsonElement(value));
        }
    }catch(Exception e){
        // In case of unexpected structure, return empty result
        return new LinkedHashMap<>();
    }
    return result;
}

private Object convertJsonElement(JsonElement element){
    if(element == null || element.isJsonNull()){
        return null;
    }
    try{
        if(element.isJsonPrimitive()){
            JsonPrimitive prim = element.getAsJsonPrimitive();
            if(prim.isBoolean()){
                return prim.getAsBoolean();
            }else if(prim.isNumber()){
                Number num = prim.getAsNumber();
                // Preserve integer types when possible
                if(num.doubleValue() == num.longValue()){
                    if(num.longValue() >= Integer.MIN_VALUE && num.longValue() <= Integer.MAX_VALUE){
                        return num.intValue();
                    }
                    return num.longValue();
                }
                return num.doubleValue();
            }else if(prim.isString()){
                return prim.getAsString();
            }else{
                return prim.getAsString();
            }
        }else if(element.isJsonArray()){
            List<Object> list = new ArrayList<>();
            for(JsonElement sub : element.getAsJsonArray()){
                list.add(convertJsonElement(sub));
            }
            return list;
        }else if(element.isJsonObject()){
            return buildContent(element.getAsJsonObject());
        }
    }catch(Exception e){
        // fall back to string representation
    }
    return element.toString();
}

