private int computeBinaryLog(int n){
    if (n <= 0) {
        throw new IllegalArgumentException("Input must be a positive integer");
    }
    try {
        // Integer numberOfLeadingZeros returns the number of leading zero bits
        // in the two's complement binary representation of the int.
        // For positive n, (32 - leadingZeros) gives floor(log2(n)) + 1
        return 32 - Integer.numberOfLeadingZeros(n);
    } catch (Exception e){
        // Wrap any unexpected errors in an IllegalArgumentException
        throw new IllegalArgumentException("Failed to compute binary log", e);
    }
}

private Set<V> intersection(Set<V> set1, Set<V> set2) {
    if (set1 == null || set2 == null) {
        return java.util.Collections.emptySet();
    }
    // Iterate over the smaller set for efficiency
    if (set1.size() > set2.size()) {
        Set<V> temp = set1;
        set1 = set2;
        set2 = temp;
    }
    java.util.Set<V> result = new java.util.HashSet<>(set1.size());
    for (V element : set1) {
        if (set2.contains(element)) {
            result.add(element);
        }
    }
    return result;
}

