private JsonObject convertProperties(List<KeyStringValuePair> properties) {
    JsonObject json = new JsonObject();
    if (properties == null) {
        return json;
    }
    for (KeyStringValuePair pair : properties) {
        try {
            if (pair == null) {
                continue;
            }
            // Try typical getter methods; fall back to fields if necessary
            String key = null;
            String value = null;
            try {
                key = pair.getKey();
            } catch (NoSuchMethodError | UnsupportedOperationException e) {
                // attempt to access field directly
                try {
                    java.lang.reflect.Field keyField = pair.getClass().getDeclaredField("key");
                    keyField.setAccessible(true);
                    key = (String) keyField.get(pair);
                } catch (Exception ignore) {
                }
            }
            try {
                value = pair.getValue();
            } catch (NoSuchMethodError | UnsupportedOperationException e) {
                try {
                    java.lang.reflect.Field valueField = pair.getClass().getDeclaredField("value");
                    valueField.setAccessible(true);
                    value = (String) valueField.get(pair);
                } catch (Exception ignore) {
                }
            }
            if (key == null) {
                continue;
            }
            if (value == null) {
                // GSON supports null values; use add(key, null)
                json.add(key, null);
            } else {
                json.addProperty(key, value);
            }
        } catch (Exception e) {
            // If any unexpected error occurs, skip this pair
            continue;
        }
    }
    return json;
}

