private int cleanup(Category node, boolean isRoot) {
    int count = 0;
    if (node == null) {
        return 0;
    }
    try {
        List<Category> children = node.getChildren();
        if (children != null) {
            Iterator<Category> it = children.iterator();
            while (it.hasNext()) {
                Category child = it.next();
                count += cleanup(child, false);
            }
        }
        if (!node.isActive()) {
            if (isRoot) {
                root = null;
            } else {
                Category parent = node.getParent();
                if (parent != null) {
                    parent.removeChild(node);
                }
            }
            count++;
        }
    } catch (Exception e) {
        // If a particular node or its children cause an exception, skip it
        // and continue processing the rest of the tree.
    }
    return count;
}

