        throw new IllegalStateException("Buffer has not been initialized");
    }
    try {
        // Append the event to the end of the buffer in a thread‑safe manner
        synchronized (this) {
            buffer.add(event);
        }
    } catch (RuntimeException e) {
        // Wrap any underlying exception so callers receive a clear message
        throw new IllegalStateException("Failed to add event to buffer", e);
    }
}

