public ByteVector putByteArray(final byte[] byteArrayValue, final int byteOffset, final int byteLength) {
    // Validate length
    if (byteLength < 0) {
        throw new IndexOutOfBoundsException("byteLength must be non‑negative, got " + byteLength);
    }

    // If we need to write data, ensure we have enough capacity
    int requiredCount = this.count + byteLength;
    if (requiredCount > data.length) {
        // Grow the internal buffer (double the size or match required, whichever is larger)
        int newCapacity = Math.max(requiredCount, data.length * 2);
        byte[] newData = new byte[newCapacity];
        System.arraycopy(data, 0, newData, 0, this.count);
        data = newData;
    }

    // If the source array is null, just write zero bytes
    if (byteArrayValue == null) {
        for (int i = 0; i < byteLength; i++) {
            data[this.count++] = 0;
        }
        return this;
    }

    // Validate offset and length with respect to the source array
    if (byteOffset < 0 || byteOffset > byteArrayValue.length) {
        throw new IndexOutOfBoundsException(
            "byteOffset out of range: " + byteOffset + ", array length: " + byteArrayValue.length);
    }
    if (byteLength > byteArrayValue.length - byteOffset) {
        throw new IndexOutOfBoundsException(
            "byteLength exceeds the bounds of the source array: offset " + byteOffset +
            ", length " + byteLength + ", array length: " + byteArrayValue.length);
    }

    // Copy the bytes
    System.arraycopy(byteArrayValue, byteOffset, data, this.count, byteLength);
    this.count += byteLength;

    return this;
}

