    // Handle null input: returning null if original string is null
    if (inString == null) {
        return null;
    }
    // If charsToDelete is null or empty, nothing to delete
    if (charsToDelete == null || charsToDelete.isEmpty()) {
        return inString;
    }

    /*
     * Build a lookup table for characters to delete.
     * Using a boolean array covering the basic Unicode range (0-65535)
     * provides O(1) lookup per character.
     */
    boolean[] deleteSet = new boolean[65536];
    for (int i = 0; i < charsToDelete.length(); i++) {
        deleteSet[charsToDelete.charAt(i)] = true;
    }

    StringBuilder result = new StringBuilder(inString.length());
    for (int i = 0; i < inString.length(); i++) {
        char c = inString.charAt(i);
        if (!deleteSet[c]) {
            result.append(c);
        }
    }

    return result.toString();
}

