public int appendLoopOnAppenders(LoggingEvent event){
    // Guard against null event – nothing to append
    if (event == null) {
        return 0;
    }

    int appended = 0;
    try {
        // It is common for logging frameworks to keep a list of appenders.
        // If the list is null or empty, nothing to do.
        if (appenders == null || appenders.isEmpty()) {
            return 0;
        }

        // Iterate over a copy to avoid concurrent modification
        for (Appender appender : new java.util.ArrayList<Appender>(appenders)) {
            if (appender == null) {
                continue;
            }
            try {
                appender.doAppend(event);
                appended++;
            } catch (Throwable t) {
                // Log the error internally if possible but do not abort
                // Logging the exception could be forwarded to a system logger or ignored
            }
        }
    } catch (Throwable e) {
        // In case the appenders list is not thread‑safe or any other unexpected error occurs
        // we swallow the exception to avoid breaking the caller
    }
    return appended;
}

