protected GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph){
    if (tour == null || graph == null) {
        throw new IllegalArgumentException("Tour and graph must not be null");
    }
    // Handle the trivial empty case
    if (tour.isEmpty()) {
        return new DefaultGraphPath<>(graph, new ArrayList<V>(), new ArrayList<E>());
    }

    // Copy the set so we can mutably remove edges
    Set<E> remaining = new HashSet<E>(tour);
    // Pick an arbitrary starting edge
    Iterator<E> it = remaining.iterator();
    E first = it.next();
    it.remove();

    List<E> orderedEdges = new ArrayList<E>();
    List<V> orderedVertices = new ArrayList<V>();

    V startVertex = graph.getEdgeSource(first);
    if (startVertex == null) {
        throw new IllegalArgumentException("Edge source cannot be null");
    }
    orderedVertices.add(startVertex);
    orderedEdges.add(first);
    V currentVertex = graph.getEdgeTarget(first);
    if (currentVertex == null) {
        throw new IllegalArgumentException("Edge target cannot be null");
    }

    // If the graph is directed we just follow source->target.
    // If it is undirected or the edge is reversed we try to flip.
    boolean directed = graph.getType().isDirected();

    while (!remaining.isEmpty()) {
        E next = null;
        for (E e : remaining) {
            V src = graph.getEdgeSource(e);
            V tgt = graph.getEdgeTarget(e);
            boolean match;
            if (directed) {
                match = src.equals(currentVertex);
            } else {
                match = src.equals(currentVertex) || tgt.equals(currentVertex);
            }
            if (match) {
                next = e;
                break;
            }
        }

        if (next == null) {
            // No connecting edge found – terminate the path
            break;
        }

        orderedEdges.add(next);
        V src = graph.getEdgeSource(next);
        V tgt = graph.getEdgeTarget(next);
        V nextVertex = src.equals(currentVertex) ? tgt : src;
        orderedVertices.add(nextVertex);
        currentVertex = nextVertex;
        remaining.remove(next);
    }

    return new DefaultGraphPath<>(graph, orderedVertices, orderedEdges);
}

