int addConstantNameAndType(final String name,final String descriptor){
    // Validate arguments
    if (name == null || descriptor == null) {
        throw new IllegalArgumentException("name and descriptor cannot be null");
    }

    try {
        // Ensure the UTF‑8 constants for name and descriptor exist
        int nameIdx = this.addConstantUtf8(name);
        int descriptorIdx = this.addConstantUtf8(descriptor);

        // Look up an existing NameAndType entry
        // We use a 64‑bit key composed of the two indices
        long key = (((long) nameIdx) << 32) | (descriptorIdx & 0xFFFFFFFFL);
        Integer existingIdx = this.nameAndTypeIndexMap.get(key);
        if (existingIdx != null) {
            return existingIdx;
        }

        // Create a new NameAndType constant and record its index
        int newIndex = this.constantPool.size(); // next free index
        this.constantPool.add(new ConstantPoolInfo.NameAndType(nameIdx, descriptorIdx));
        this.nameAndTypeIndexMap.put(key, newIndex);
        return newIndex;
    } catch (Exception e) {
        // Wrap unexpected errors
        throw new RuntimeException("Failed to add Constant.NameAndType", e);
    }
}

private String unescapeId(String input){
    // Return null for null input
    if (input == null) {
        return null;
    }
    int len = input.length();
    // Only attempt unescaping if the string is quoted with double quotes
    if (len >= 2 && input.charAt(0) == '"' && input.charAt(len - 1) == '"') {
        String inner = input.substring(1, len - 1);
        StringBuilder sb = new StringBuilder(inner.length());
        for (int i = 0; i < inner.length(); ) {
            char c = inner.charAt(i);
            if (c == '\\' && i + 1 < inner.length()) {
                char next = inner.charAt(i + 1);
                switch (next) {
                    case '\\':
                        sb.append('\\');
                        i += 2;
                        break;
                    case '\"':
                        sb.append('\"');
                        i += 2;
                        break;
                    case 'n':
                        sb.append('\n');
                        i += 2;
                        break;
                    case 'r':
                        sb.append('\r');
                        i += 2;
                        break;
                    case 't':
                        sb.append('\t');
                        i += 2;
                        break;
                    case 'b':
                        sb.append('\b');
                        i += 2;
                        break;
                    case 'f':
                        sb.append('\f');
                        i += 2;
                        break;
                    case '0':
                        sb.append('\0');
                        i += 2;
                        break;
                    case 'x':
                        // parse two hex digits
                        if (i + 3 < inner.length()) {
                            String hex = inner.substring(i + 2, i + 4);
                            try {
                                sb.append((char) Integer.parseInt(hex, 16));
                            } catch (NumberFormatException e) {
                                // If parsing fails, keep the raw sequence
                                sb.append('\\').append('x').append(hex);
                            }
                            i += 4;
                        } else {
                            // Invalid escape, just keep the backslash
                            sb.append('\\');
                            i++;
                        }
                        break;
                    default:
                        // Treat unrecognized escape sequences as the literal character
                        sb.append(next);
                        i += 2;
                        break;
                }
            } else {
                sb.append(c);
                i++;
            }
        }
        return sb.toString();
    }
    // Return the string as-is if it's not a quoted identifier
    return input;
}

