public static int countOccurrencesOf(String str, String sub) {
    // Return 0 for null inputs as specified
    if (str == null || sub == null) {
        return 0;
    }
    // Empty substring cannot be matched meaningfully
    if (sub.isEmpty()) {
        return 0;
    }

    int count = 0;
    int index = 0;
    while (true) {
        index = str.indexOf(sub, index);
        if (index == -1) {
            break;
        }
        count++;
        // Move forward by one to allow overlapping matches
        index = index + 1;
    }
    return count;
}

