    List<SequenceRange> ranges = new ArrayList<>();
    try {
        // Fetch current snapshots from the existing data store or service.
        // The actual retrieval logic depends on the surrounding code base.
        // Here we assume there is a method getCurrentProfileSegmentSnapshots() that returns a List of snapshots.
        List<ProfileSegmentSnapshot> snapshots = getCurrentProfileSegmentSnapshots();
        if (snapshots != null) {
            for (ProfileSegmentSnapshot snapshot : snapshots) {
                if (snapshot != null) {
                    int start = snapshot.getStartIndex();
                    int end = snapshot.getEndIndex();
                    if (start <= end) {
                        ranges.add(new SequenceRange(start, end));
                    } else {
                        // If indices are reversed, swap them to maintain a valid range.
                        ranges.add(new SequenceRange(end, start));
                    }
                }
            }
        }
    } catch (Exception e) {
        // Log the exception (or rethrow as needed). Here we simply print the stack trace for visibility.
        System.err.println("Error while building sequence ranges: " + e);
    }
    return ranges;
}

