private String parseToken(final char[] terminators) {
    // Safety check for the input being null or out of bounds
    if (input == null) {
        return null;
    }

    int start = pos;
    int length = input.length();

    // If already at the end of input, return empty token
    if (pos >= length) {
        return "";
    }

    // Scan until a terminator or the end of input is reached
    while (pos < length) {
        char currentChar = input.charAt(pos);
        boolean isTerminator = false;

        // If terminators array is provided, check against it
        if (terminators != null) {
            for (char term : terminators) {
                if (currentChar == term) {
                    isTerminator = true;
                    break;
                }
            }
        }

        if (isTerminator) {
            break; // stop before the terminator
        }
        pos++;
    }

    // Extract the token
    String token = input.substring(start, pos);

    // Advance past the terminator if one was found
    if (pos < length) {
        pos++;
    }

    return token;
}

