private Pair<List<Integer>,Long> computeSuffixSum(List<Integer> bounds){
    // Handle null or empty input gracefully
    if (bounds == null || bounds.isEmpty()){
        return new Pair<>(new ArrayList<>(), 0L);
    }
    int n = bounds.size();
    int[] temp = new int[n];
    long cumulative = 0;
    // Compute suffix sums from end to start
    for (int i = n - 1; i >= 0; i--) {
        cumulative += bounds.get(i);
        temp[i] = (int) cumulative; // cast to int for List<Integer>
    }
    // Convert array to List<Integer>
    List<Integer> suffixList = new ArrayList<>(n);
    for (int val : temp) {
        suffixList.add(val);
    }
    return new Pair<>(suffixList, cumulative);
}

public static final <V> void reverse(V[] arr, int from, int to) {
    if (arr == null) {
        throw new IllegalArgumentException("Array must not be null");
    }
    int len = arr.length;
    if (from < 0 || to < 0 || from >= len || to >= len) {
        throw new IllegalArgumentException("Indices are out of bounds");
    }
    if (from > to) {
        throw new IllegalArgumentException("from index must be less than or equal to to index");
    }

    int i = from;
    int j = to;
    while (i < j) {
        V temp = arr[i];
        arr[i] = arr[j];
        arr[j] = temp;
        i++;
        j--;
    }
}

private static boolean startsWith(final String str, final String prefix, final boolean ignoreCase) {
    // If both are null, consider it a valid start
    if (str == null && prefix == null) {
        return true;
    }
    // If either is null (but not both), it's not a match
    if (str == null || prefix == null) {
        return false;
    }

    int prefixLength = prefix.length();

    // If the prefix is longer than the target string, it cannot match
    if (prefixLength > str.length()) {
        return false;
    }

    // Perform case-sensitive or case-insensitive comparison
    if (ignoreCase) {
        return str.regionMatches(true, 0, prefix, 0, prefixLength);
    } else {
        return str.startsWith(prefix);
    }
}

