public void putAllWriteable(BeanMap map){
    if (map == null) {
        throw new IllegalArgumentException("map cannot be null");
    }
    // Iterate over the properties of this BeanMap
    for (Object keyObj : keySet()) {
        // Property names should be strings
        if (!(keyObj instanceof String)) {
            continue;
        }
        String key = (String) keyObj;

        // Skip if this BeanMap cannot write the property
        if (!isWritable(key)) {
            continue;
        }
        // Skip if the source BeanMap cannot read the property
        if (!map.isReadable(key)) {
            continue;
        }

        try {
            Object value = map.get(key); // Read the value from the source map
            put(key, value);             // Write the value into this map
        } catch (Exception ignored) {
            // Ignore properties that cause problems (e.g., type mismatch, illegal state)
        }
    }
}

