    try {
        if (table == null || pane == null) {
            return;
        }
        int rowCount = table.getRowCount();
        if (row < 0 || row >= rowCount) {
            return;
        }
        // Select the specified row (and keep other selections cleared)
        table.clearSelection();
        table.setRowSelectionInterval(row, row);
        // Ensure the first column is visible so the rowRect can be computed
        table.setColumnSelectionInterval(0, 0);

        // Scroll the row into view
        java.awt.Rectangle cellRect = table.getCellRect(row, 0, true);
        if (cellRect != null) {
            table.scrollRectToVisible(cellRect);
        }

        // Delay repaint to allow the table to paint the newly selected row
        javax.swing.Timer repaintTimer = new javax.swing.Timer(50, e -> {
            table.repaint();
            pane.repaint();
            ((javax.swing.Timer) e.getSource()).stop();
        });
        repaintTimer.setRepeats(false);
        repaintTimer.start();
    } catch (Exception e) {
        // Fail silently – nothing can be done if UI components are not ready
    }
}

public ByteVector putInt(final int intValue){
    // Ensure there is enough space for 4 additional bytes
    if (count + 4 > raw.length) {
        int newSize = raw.length + Math.max(GROW_SIZE, (count + 4) - raw.length);
        byte[] newRaw = new byte[newSize];
        System.arraycopy(raw, 0, newRaw, 0, count);
        raw = newRaw;
    }
    // Write the int in big-endian order
    raw[count++] = (byte) (intValue >>> 24);
    raw[count++] = (byte) (intValue >>> 16);
    raw[count++] = (byte) (intValue >>> 8);
    raw[count++] = (byte) intValue;
    return this;
}

public static boolean arrayequals(byte[] a,byte[] b,int count){
    // Quick checks for obvious mismatches
    if (a == null || b == null) {
        return false;
    }
    if (count < 0) {
        // Negative count cannot be satisfied
        return false;
    }
    // If count is zero, empty prefixes are always equal
    if (count == 0) {
        return true;
    }
    if (count > a.length || count > b.length) {
        // Not enough elements to compare
        return false;
    }
    // If both references point to the same array and the requested count
    // does not exceed its length, the prefixes are trivially equal.
    if (a == b) {
        return true;
    }
    for (int i = 0; i < count; i++) {
        if (a[i] != b[i]) {
            return false;
        }
    }
    return true;
}

