private static <V, E> boolean isClique(Graph<V, E> graph, Set<V> vertices) {
    // Validate inputs
    if (graph == null || vertices == null) {
        return false;
    }
    // Trivial cases
    if (vertices.size() <= 1) {
        return true;
    }
    // Ensure all vertices exist in the graph
    for (V v : vertices) {
        if (!graph.containsVertex(v)) {
            return false;
        }
    }
    // Convert to a list for indexed access
    List<V> list = new ArrayList<>(vertices);
    int n = list.size();
    try {
        for (int i = 0; i < n; i++) {
            V vi = list.get(i);
            for (int j = i + 1; j < n; j++) {
                V vj = list.get(j);
                // A clique requires an edge between every pair of distinct vertices
                if (graph.getEdge(vi, vj) == null) {
                    return false;
                }
            }
        }
    } catch (Exception e) {
        // Any runtime exception (e.g., unsupported edge queries) results in a negative result
        return false;
    }
    return true;
}

