private List<Integer> computeUpperBounds(List<K> keys){
    try {
        if (keys == null) {
            return new ArrayList<>();
        }
        List<Integer> bounds = new ArrayList<>(keys.size());
        for (K key : keys) {
            if (key == null) {
                bounds.add(0);
                continue;
            }
            if (key instanceof Integer) {
                bounds.add(((Integer) key) + 1);
            } else if (key instanceof Long) {
                long val = (Long) key;
                bounds.add((int) Math.min(val + 1, Integer.MAX_VALUE));
            } else if (key instanceof Number) {
                double d = ((Number) key).doubleValue();
                bounds.add((int) Math.floor(d) + 1);
            } else if (key instanceof CharSequence) {
                bounds.add(((CharSequence) key).length());
            } else {
                bounds.add(0);
            }
        }
        return bounds;
    } catch (Exception e) {
        return new ArrayList<>();
    }
}

