public static String applyRelativePath(String path, String relativePath) {
    try {
        if (path == null || relativePath == null) {
            return null;
        }
        // If relativePath is empty, just return the original path (or its directory)
        if (relativePath.isEmpty()) {
            return path;
        }

        boolean isAbsolute = path.startsWith("/");
        // Determine base directory (remove file name if any)
        String base = path;
        int lastSlash = base.lastIndexOf('/');
        if (lastSlash != -1) {
            base = base.substring(0, lastSlash);
        } else {
            // No slash in path; treat base as empty (relative to current working dir)
            base = "";
        }

        // Split base into components
        java.util.List<String> parts = new java.util.ArrayList<>();
        if (!base.isEmpty()) {
            for (String p : base.split("/")) {
                if (!p.isEmpty()) {
                    parts.add(p);
                }
            }
        }

        // Process relative parts
        String[] relParts = relativePath.split("/");
        for (String r : relParts) {
            if (r.isEmpty() || r.equals(".")) {
                continue; // no effect
            }
            if (r.equals("..")) {
                if (!parts.isEmpty()) {
                    parts.remove(parts.size() - 1); // go up one level
                }
                // if parts is empty, stay at root (do nothing)
            } else {
                parts.add(r);
            }
        }

        // Construct final path
        StringBuilder sb = new StringBuilder();
        if (isAbsolute) {
            sb.append("/");
        }
        for (int i = 0; i < parts.size(); i++) {
            sb.append(parts.get(i));
            if (i < parts.size() - 1) {
                sb.append("/");
            }
        }
        // If result is empty and absolute, return "/" to represent root
        if (sb.length() == 0 && isAbsolute) {
            return "/";
        }
        return sb.toString();
    } catch (Exception e) {
        // In case of any unexpected error, return null
        return null;
    }
}

