        return;
    }
    byte[] data = formatted.getBytes(java.nio.charset.StandardCharsets.UTF_8);
    for (Client client : clients) {
        try {
            java.io.OutputStream os = client.getOutputStream();
            os.write(data);
            os.flush();
        } catch (java.io.IOException e) {
            // A write error likely means the client has disconnected or is otherwise unavailable
            // Remove the client from the collection so future events are not sent to it
            removeClient(client);
        }
    }
}

public static String toString(final char ch) {
    // Return a String that contains the provided character.
    // For simplicity and correctness, use String.valueOf which already
    // handles all valid char values.  This method works for any char
    // (including extended Unicode) and always produces a non-null
    // String of length 1.
    return String.valueOf(ch);
}

public int readTag() throws IOException {
    int tag = 0;
    int shift = 0;
    while (true) {
        int b = in.read();
        if (b == -1) {
            // EOF reached before reading any tag; return 0 as per protocol spec
            return 0;
        }
        tag |= (b & 0x7F) << shift;
        if ((b & 0x80) == 0) {
            break; // completed the varint
        }
        shift += 7;
        // A 32‑bit varint can be at most 5 bytes (35 bits)
        if (shift > 28) {
            throw new IOException("Malformed varint");
        }
    }
    return tag;
}

private String buildContentRange() {
    // Build a Content-Range header value in the form:
    // "bytes <start>-<end>/<total>"
    try {
        long start = this.byteRangeStart;
        long end   = this.byteRangeEnd;
        long total = this.contentLength;

        if (total <= 0) {
            throw new IllegalStateException("Content length must be positive");
        }
        if (start < 0 || end < start) {
            throw new IllegalStateException(
                "Invalid byte range: start=" + start + ", end=" + end);
        }

        return "bytes " + start + "-" + end + "/" + total;
    } catch (Exception e) {
        throw new IllegalStateException("Cannot build Content‑Range header", e);
    }
}

public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
    if (file == null) {
        throw new IllegalArgumentException("file cannot be null");
    }
    if (!file.exists() || !file.isFile()) {
        throw new IllegalArgumentException("File does not exist or is not a regular file: " + file);
    }

    List<ThreadSnapshot> result = new ArrayList<>();

    try (BufferedReader reader = new BufferedReader(new FileReader(file))) {
        String line;
        while ((line = reader.readLine()) != null) {
            line = line.trim();
            if (line.isEmpty()) {
                continue;
            }

            // Expected line format: <timestamp>,<data>
            int commaIdx = line.indexOf(',');
            if (commaIdx < 0) {
                continue; // skip malformed line
            }

            long timestamp;
            try {
                timestamp = Long.parseLong(line.substring(0, commaIdx).trim());
            } catch (NumberFormatException e) {
                continue; // skip if timestamp cannot be parsed
            }

            String data = line.substring(commaIdx + 1).trim();

            // If timeRanges are null or empty, accept all snapshots
            boolean withinRange = true;
            if (timeRanges != null && !timeRanges.isEmpty()) {
                withinRange = false;
                for (ProfileAnalyzeTimeRange range : timeRanges) {
                    if (range == null) {
                        continue;
                    }
                    try {
                        long start = range.getStart();
                        long end = range.getEnd();
                        if (timestamp >= start && timestamp <= end) {
                            withinRange = true;
                            break;
                        }
                    } catch (Exception e) {
                        // ignore problematic range entries
                    }
                }
            }

            if (!withinRange) {
                continue;
            }

            try {
                result.add(new ThreadSnapshot(timestamp, data));
            } catch (Exception e) {
                // Skip snapshot creation if constructor fails
            }
        }
    }

    return result;
}
